package com.warehouse.service; import com.warehouse.domain.*; import com.warehouse.repo.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class StockServiceTest { @Mock ItemRepository items; @Mock TransactionRepository txs; @Mock AlertRepository alerts; StockService service; Item item; @BeforeEach void init(){MockitoAnnotations.openMocks(this);service=new StockService(items,txs,alerts);item=new Item();item.id=UUID.randomUUID();item.quantity=3;item.lowStockThreshold=2;when(items.findById(item.id)).thenReturn(Optional.of(item));} @Test void rejectsNegativeStock(){assertThrows(IllegalStateException.class,()->service.record(item.id,TransactionType.OUT,4,"",null));} @Test void createsAlertAtThreshold(){when(alerts.existsByItemIdAndStatusNot(any(),any())).thenReturn(false);service.record(item.id,TransactionType.OUT,1,"",null);verify(alerts).save(any(Alert.class));} }
